"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["45680"],{79776(e){e.exports=JSON.parse('{"id":"FIN-164","slug":"retained-earnings","term":"Retained Earnings","also_known_as":[],"difficulty":"Beginner","definition":"Retained earnings are the total profits a company has kept in the business over its life, rather than paying out to shareholders as dividends.","explanation":["Each year, a company\'s net income is either paid out as dividends or kept in the business. The portion kept is added to retained earnings, which is part of shareholders\' equity on the balance sheet.","The calculation is straightforward: opening retained earnings, plus net income for the year, minus dividends declared. If a company starts the year with retained earnings of 3 million, earns net income of 800,000 and pays dividends of 300,000, its retained earnings at year-end are 3.5 million.","Retained earnings do not sit in a separate pile of cash. The profits have usually been reinvested in assets such as equipment, inventory or new projects, or used to repay debt.","If a company makes losses, retained earnings fall and can become negative, which is often called an accumulated deficit. Young, fast-growing companies frequently have accumulated deficits because they have spent heavily before becoming profitable. Mature companies with long profit histories often have very large retained earnings."],"note":"","total":1500,"prev":{"slug":"retail-investor","term":"Retail Investor"},"next":{"slug":"retention-ratio","term":"Retention Ratio"}}')}}]);